#!/usr/bin/env python
# -*- coding: utf-8 -*-
"""Generate the Python Learn course files."""
import json, os, sys

os.chdir(os.path.dirname(os.path.abspath(__file__)))

# Generate course.json using Python dict (avoids quote issues)
course = {}

def add_lesson(lid, title, ltype="", part=0, exercises=None, project_code=""):
    if exercises is None: exercises = []
    lesson = {"title": title, "exercises": []}
    for q, a, h in exercises:
        lesson["exercises"].append({"question": q, "answer": a, "hint": h})
    if ltype: lesson["type"] = ltype
    if part > 0: lesson["project_part"] = part
    if project_code: lesson["project_code"] = project_code
    course[str(lid)] = lesson

