add_lesson(82,"Errors and exceptions","",0,[("Handle exceptions with try/except",'try:\n    x = int(input("Num: "))\n    print(f"You entered {x}")\nexcept ValueError:\n    print("That was not a number!")','Use try/except')])
add_lesson(83,"Raising exceptions","",0,[("Raise your own exceptions",'def divide(a, b):\n    if b == 0: raise ValueError("Cannot divide by zero")\n    return a / b\ntry:\n    print(divide(10, 0))\nexcept ValueError as e:\n    print(f"Error: {e}")','Use raise keyword')])
add_lesson(84,"Errors and exceptions","PRACTICE",0,[("Create robust division function",'def safe_divide(a, b):\n    try:\n        return a / b\n    except ZeroDivisionError:\n        return None\n    except TypeError:\n        return "Invalid input"\nprint(safe_divide(10, 2))\nprint(safe_divide(10, 0))','Use multiple except blocks')])
add_lesson(85,"Handling multiple exception types","",0,[("Handle different exception types",'try:\n    f = open("file.txt")\n    data = f.read()\n    num = int(data)\nexcept FileNotFoundError:\n    print("File not found")\nexcept ValueError:\n    print("Not a valid number")\nfinally:\n    print("Cleanup done")','Multiple except blocks')])
add_lesson(86,"Working with exception messages","",0,[("Create custom exception messages",'class NegativeError(Exception):\n    pass\ndef process(n):\n    if n < 0: raise NegativeError(f"{n} is negative!")\ntry:\n    process(-5)\nexcept NegativeError as e:\n    print(f"Custom error: {e}")','Define custom exception class')])
add_lesson(87,"Exception handling","PRACTICE",0,[("Create file reader with error handling",'def read_number(filename):\n    try:\n        with open(filename) as f:\n            return float(f.read().strip())\n    except FileNotFoundError:\n        print("File missing")\n    except ValueError:\n        print("Not a number")\n    return None\nprint(read_number("data.txt"))','Use try/except/finally with files')])
add_lesson(88,"Best practices in exception handling","",0,[("Follow best practices",'# Be specific with exception types\n# Never use bare except:\n# Use finally for cleanup','Best practice patterns')])
add_lesson(89,"Exceptions","PRACTICE",0,[("Create a robust calculator",'def calc(a, b, op):\n    try:\n        a, b = float(a), float(b)\n        if op == "+": return a+b\n        elif op == "-": return a-b\n        elif op == "*": return a*b\n        elif op == "/":\n            if b==0: raise ZeroDivisionError\n            return a/b\n        else: raise ValueError(f"Unknown op: {op}")\n    except (ValueError, ZeroDivisionError) as e:\n        return f"Error: {e}"\nprint(calc(10, 5, "+"))\nprint(calc(10, 0, "/"))','Combine all error handling')])
add_lesson(90,"Sensor Reading Validator - Part 1","PROJECT_GUIDED",1,[("Validate sensor readings",'import random\nclass InvalidReadingError(Exception):\n    pass\ndef read_sensor():\n    val = random.uniform(-10, 50)\n    if val < 0 or val > 40: raise InvalidReadingError(f"Invalid reading: {val}")\n    return val\nreadings = []\nfor i in range(10):\n    try:\n        r = read_sensor()\n        readings.append(r)\n        print(f"Reading {i+1}: {r:.2f}")\n    except InvalidReadingError as e: print(f"Error: {e}")\nif readings: print(f"Valid readings: {len(readings)}/10")','Use custom exceptions and loops')],"import random\nclass InvalidReadingError(Exception):\n    pass\ndef read_sensor():\n    val = random.uniform(-10, 50)\n    if val < 0 or val > 40: raise InvalidReadingError(f'Invalid reading: {val}')\n    return val\nreadings = []\nfor i in range(10):\n    try:\n        r = read_sensor()\n        readings.append(r)\n        print(f'Reading {i+1}: {r:.2f}')\n    except InvalidReadingError as e: print(f'Error: {e}')\nif readings: print(f'Valid readings: {len(readings)}/10')\n")

